    low = str(text or '').lower()
    mon = None
    for i, name in enumerate(MO):
        if re.search(r'\b' + name[:3], low):
            mon = i + 1
            break
    nums = [int(x) for x in re.findall(r'\b(\d{1,2})(?:st|nd|rd|th)?\b', low)]
